import gzip, csv
from collections import defaultdict, Counter

rows = []
with gzip.open("data/erate_frn_status_fy2024.csv.gz", "rt", encoding="utf-8", errors="replace", newline="") as fh:
    for row in csv.DictReader(fh):
        rows.append({k:(v or "").strip() for k,v in row.items()})

byfrn = defaultdict(dict)
for r in rows:
    byfrn[r["funding_request_number"]][r["form_version"]] = r

def f(x):
    try: return float(x)
    except: return None

stats = defaultdict(Counter)
for frn, v in byfrn.items():
    if "Current" not in v or "Original" not in v: continue
    c, o = v["Current"], v["Original"]
    tok = c["form_471_frn_status_name"]
    st = stats[tok]
    st["n"] += 1
    # ignore commitment (that's the decision itself); look at pre-discount, months, dis_pct
    for col in ["total_pre_discount_costs","months_of_service","dis_pct"]:
        if o[col] and c[col] and f(o[col]) != f(c[col]):
            st[f"{col}_moved"] += 1
    if o["funding_commitment_request"] and c["funding_commitment_request"] and f(o["funding_commitment_request"]) != f(c["funding_commitment_request"]):
        st["commit_moved"] += 1
    # categorical churn
    for col in ["contract_type_name","bid_count","organization_name"]:
        if o[col] != c[col]:
            st[f"{col}_moved"] += 1

for tok in ["QK7","VR9","ZP2","VD4"]:
    st = stats[tok]
    n = st["n"]
    print(tok, f"n={n}", {k: f"{v} ({v/n:.3f})" for k,v in st.items() if k!="n"})

# also: wave_sequence_number distributions per token
print("\nwave values per token (top):")
for tok in ["QK7","VR9","ZP2","VD4"]:
    waves = Counter(v["Current"]["wave_sequence_number"] for v in byfrn.values()
                    if "Current" in v and v["Current"]["form_471_frn_status_name"]==tok)
    print(tok, waves.most_common(8))
EOF

