import gzip, csv
from collections import defaultdict

rows = []
with gzip.open("data/erate_frn_status_fy2024.csv.gz", "rt", encoding="utf-8", errors="replace", newline="") as fh:
    for row in csv.DictReader(fh):
        rows.append({k:(v or "").strip() for k,v in row.items()})

byfrn = defaultdict(dict)
for r in rows:
    byfrn[r["funding_request_number"]][r["form_version"]] = r

def f(x):
    try: return float(x)
    except: return None

cands = {"ZP2_typ": [], "VD4_typ": [], "VR9_typ": [], "QK7_zero_appeal": [], "QK7_zero_noappeal": [], "QK7_missing": [], "VR9_zero": []}
for frn, v in byfrn.items():
    c = v.get("Current")
    if not c: continue
    tok = c["form_471_frn_status_name"]
    fcr = f(c["funding_commitment_request"])
    if tok=="ZP2" and fcr==0 and not c["appeal_wave_number"] and c["wave_sequence_number"]:
        cands["ZP2_typ"].append(frn)
    if tok=="VD4" and fcr==0 and not c["appeal_wave_number"] and c["wave_sequence_number"]:
        cands["VD4_typ"].append(frn)
    if tok=="VR9" and fcr and fcr>0:
        cands["VR9_typ"].append(frn)
    if tok=="QK7" and fcr==0 and c["appeal_wave_number"]:
        cands["QK7_zero_appeal"].append(frn)
    if tok=="QK7" and fcr==0 and not c["appeal_wave_number"]:
        cands["QK7_zero_noappeal"].append(frn)
    if tok=="QK7" and not c["funding_commitment_request"]:
        cands["QK7_missing"].append(frn)
    if tok=="VR9" and fcr==0:
        cands["VR9_zero"].append(frn)

for k, v in cands.items():
    print(k, len(v), v[:3])
EOF

